// Validation tab: the web engine vs. MATLAB (Phased Array System Toolbox,
// Radar Toolbox, and ITU models). Reference vectors are generated by matlab/fase*/val_*.m.
import { useMemo, useState } from 'react';
import { allChecks, passes, type Check } from '../validation/compare';
import refAntena from '../validation/ref_antena.json';
import { Panel, fmt } from '../ui/controls';
import { LinePlot } from './LinePlot';
import { dict, phrases, tr } from '../i18n';
import { VAL_EN, VAL_FRAGS } from '../i18nEngine';

const V = (s: string) => phrases(s, VAL_EN, VAL_FRAGS);

const FINDINGS = (): { titulo: string; texto: string; tipo: 'bug' | 'mejora' | 'metodo' | 'limite' }[] => [
  { tipo: 'bug', titulo: tr('Pd de Swerling 0 mal invertida', 'Swerling 0 Pd wrongly inverted'),
    texto: tr('La inversión de Albersheim olvidaba el término (6,2 + 4,54/√1,44)·log10(·). Error de 8 a 20 dB en la SNR requerida; corregido (ahora ≤ 0,26 dB frente a detectability).', 'The Albersheim inversion missed the term (6.2 + 4.54/√1.44)·log10(·). Error of 8 to 20 dB in the required SNR; fixed (now ≤ 0.26 dB versus detectability).') },
  { tipo: 'bug', titulo: tr('Coeficientes de lluvia de P.838', 'P.838 rain coefficients'),
    texto: tr('Los coeficientes k de la tabla eran hasta 2,5 veces distintos de ITU-R P.838-3. Sustituidos por la tabla extraída de rainpl con paso de 0,1 GHz (error < 0,01 %).', 'The k coefficients in the table differed by up to 2.5 times from ITU-R P.838-3. Replaced by a table extracted from rainpl with a 0.1 GHz step (error < 0.01 %).') },
  { tipo: 'bug', titulo: tr('Atenuación de gases con aire cálido y húmedo', 'Gaseous attenuation in warm, humid air'),
    texto: tr('La aproximación del anexo 2 de P.676 se quedaba hasta un 22 % corta frente a gaspl (≈ 1 dB en 300 km de ida y vuelta). Sustituida por una tabla generada con gaspl e interpolación multilineal (error < 2 %).', 'The P.676 Annex 2 approximation fell up to 22 % short of gaspl (≈ 1 dB over 300 km two-way). Replaced by a table generated with gaspl and multilinear interpolation (error < 2 %).') },
  { tipo: 'bug', titulo: tr('Distancia oblicua tratada como horizontal', 'Slant range treated as ground range'),
    texto: tr('La geometría de dos rayos recibía la distancia oblicua como distancia sobre la superficie. Despreciable para el rozaolas, pero con blancos altos y cercanos el ángulo directo salía 26,6° en vez de 30°. Corregido con la conversión por ley de cosenos.', 'The two-ray geometry took the slant range as ground range. Negligible for the sea-skimmer, but for high, close targets the direct angle came out 26.6° instead of 30°. Fixed with a law-of-cosines conversion.') },
  { tipo: 'bug', titulo: tr('Factor de forma del haz en el clutter', 'Beam-shape factor in clutter'),
    texto: tr('El 1,33 multiplicaba el área de la celda de mar; la anchura efectiva de ida y vuelta es θ3/1,33 (Barton). El clutter salía 2,5 dB alto. Corregido en la web y en MATLAB.', 'The 1.33 multiplied the sea-cell area; the effective two-way width is θ3/1.33 (Barton). Clutter came out 2.5 dB high. Fixed in the web and in MATLAB.') },
  { tipo: 'metodo', titulo: tr('Acoplamiento: coherencia energética frente a exactitud par a par', 'Coupling: energy consistency versus pairwise accuracy'),
    texto: tr('El núcleo de MoM (Antenna Toolbox) da impedancias mutuas un 16–35 % distintas de la FEM inducida, pero no es coherente con el diagrama de elemento aislado y rompe la conservación de la energía (R_a en el plano H a 60° salía 1,7 veces la esperada). La FEM inducida cumple la relación de Hannan al 0,5 % y el |Γ| activo de ambos núcleos difiere menos de 0,007 (MoM de 21×21 con imágenes): el motor usa la FEM inducida.', 'The MoM kernel (Antenna Toolbox) gives mutual impedances 16–35 % different from induced EMF, but it is not consistent with the isolated-element pattern and breaks energy conservation (R_a in the H-plane at 60° came out 1.7 times the expected value). Induced EMF satisfies the Hannan relation to 0.5 % and the active |Γ| of both kernels differs by less than 0.007 (21×21 MoM with images): the engine uses induced EMF.') },
  { tipo: 'metodo', titulo: tr('infiniteArray no converge', 'infiniteArray does not converge'),
    texto: tr('La impedancia de barrido de infiniteArray (Antenna Toolbox) con dipolo sobre plano daba parte real negativa y no convergía al aumentar los términos de Floquet; se sustituyó por la suma directa de impedancias mutuas sobre el array finito de 80×80.', 'The infiniteArray (Antenna Toolbox) scan impedance with a dipole over a ground plane gave a negative real part and did not converge as Floquet terms increased; it was replaced by the direct sum of mutual impedances over the finite 80×80 array.') },
  { tipo: 'mejora', titulo: tr('Diferencia de caminos exacta', 'Exact path difference'),
    texto: tr('Δ = 2·h1·h2/d solo vale a rasante baja; a distancias cortas (ψ ≈ 37°) erraba en ~6 m de 23. Ahora se calcula por la imagen; coincide con un dos rayos resuelto por el principio de Fermat.', 'Δ = 2·h1·h2/d only holds at low grazing angles; at short range (ψ ≈ 37°) it was off by ~6 m out of 23. It is now computed from the image; it matches a two-ray model solved with Fermat’s principle.') },
  { tipo: 'metodo', titulo: tr('radarpropfactor en la región de interferencia', 'radarpropfactor in the interference region'),
    texto: tr('Implementa el método de Blake para diagramas de cobertura, con la diferencia de caminos de blanco lejano Δ = 2·h·sen θd. Con el blanco por debajo de la antena (rozaolas a 7 m, antena a 20 m) subestima Δ en torno al 35 % y desplaza los lóbulos. En esa región la web se valida frente a un dos rayos exacto independiente (Fermat).', 'It implements Blake’s method for coverage diagrams, with the distant-target path difference Δ = 2·h·sin θd. With the target below the antenna (sea-skimmer at 7 m, antenna at 20 m) it underestimates Δ by about 35 % and shifts the lobes. In that region the web is validated against an independent exact two-ray model (Fermat).') },
  { tipo: 'limite', titulo: tr('Limitación: sin región intermedia ni difracción', 'Limitation: no intermediate or diffraction region'),
    texto: tr('Cerca del horizonte radarpropfactor pasa a la región intermedia y de difracción; la web sigue con dos rayos y es optimista allí (varios dB para el rozaolas cerca del horizonte). Pendiente: añadir el modelo de difracción de tierra esférica.', 'Near the horizon radarpropfactor switches to the intermediate and diffraction region; the web keeps two rays and is optimistic there (several dB for the sea-skimmer near the horizon). To do: add the spherical-Earth diffraction model.') },
  { tipo: 'metodo', titulo: tr('rainpl incluye reducción de trayecto', 'rainpl includes path reduction'),
    texto: tr('A 1 km y 50 mm/h da un 28 % menos que la atenuación específica de P.838. Para comparar γ se usa un trayecto de 1 m.', 'At 1 km and 50 mm/h it gives 28 % less than the P.838 specific attenuation. A 1 m path is used to compare γ.') },
];

export function ValidationTab() {
  const { checks, overlays } = useMemo(() => allChecks(), []);
  const groups = useMemo(() => [...new Set(checks.map(c => c.grupo))], [checks]);
  const [group, setGroup] = useState<string>('todos');
  const [ov, setOv] = useState(overlays.find(x => x.id === 'bl7')?.id ?? overlays[0].id);
  const shown = group === 'todos' ? checks : checks.filter(c => c.grupo === group);
  const nOk = checks.filter(c => !c.info && passes(c)).length;
  const nInfo = checks.filter(c => c.info).length;
  const nBad = checks.filter(c => !c.info && !passes(c)).length;
  const o = overlays.find(x => x.id === ov) ?? overlays[0];

  const series = [
    { x: o.x, y: o.ref, color: '#ededf0', width: 1.6, label: o.ref2 ? tr('dos rayos exacto (MATLAB)', 'exact two-ray (MATLAB)') : 'MATLAB' },
    ...(o.ref2 ? [{ x: o.x, y: o.ref2, color: '#ff6b6b', width: 1.2, dash: [5, 4], label: 'radarpropfactor' }] : []),
    { x: o.x, y: o.web, color: '#59d8ff', width: 1.2, dash: o.ref2 ? undefined : [4, 3], label: 'web' },
  ];
  let lo = Infinity, hi = -Infinity;
  for (const s of series) for (const v of s.y) if (Number.isFinite(v)) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
  const yr: [number, number] = o.yRange ?? [Math.floor(lo - 1), Math.ceil(hi + 1)];

  return (
    <main className="grid scen-grid">
      <div className="col">
        <Panel title={tr('Resumen', 'Summary')}>
          <div className="val-summary">
            <div><b className="good">{nOk}</b><span>{tr('dentro de tolerancia', 'within tolerance')}</span></div>
            <div><b>{nInfo}</b><span>{tr('diferencias de método documentadas', 'documented method differences')}</span></div>
            <div><b className={nBad ? 'bad' : ''}>{nBad}</b><span>{tr('fuera de tolerancia', 'out of tolerance')}</span></div>
          </div>
          <p className="note">{tr('Referencias generadas con MATLAB', 'References generated with MATLAB')} {String(refAntena.meta.matlab).split(' ')[0]} {tr('el', 'on')} {refAntena.meta.generado.split(' ')[0]}. {tr('Cada comprobación es también un test automático', 'Each check is also an automated test')} (<code>tests/validation.test.ts</code>).</p>
        </Panel>
        <Panel title={tr('Bloques', 'Blocks')}>
          <div className="chips">
            {['todos', ...groups].map(gn => {
              const cs = gn === 'todos' ? checks : checks.filter(c => c.grupo === gn);
              const ok = cs.every(c => c.info || passes(c));
              return (
                <button key={gn} className={'chip' + (group === gn ? ' on' : '')} onClick={() => setGroup(gn)}>
                  <span>{gn === 'todos' ? tr('Todos', 'All') : dict(gn, VAL_EN)}</span>
                  <small>{cs.length} {tr('comprobaciones', 'checks')} · {ok ? tr('todo en tolerancia', 'all within tolerance') : tr('con fallos', 'with failures')}</small>
                </button>
              );
            })}
          </div>
        </Panel>
        <Panel title={tr('Cómo se reproduce', 'How to reproduce')}>
          <ol className="steps">
            <li><code>matlab/fase1_sistema/val_antena.m</code>: {tr('patrones y directividad', 'patterns and directivity')} (phased.URA)</li>
            <li><code>matlab/fase1_sistema/val_radar.m</code>: radareqsnr, detectability, horizonrange</li>
            <li><code>matlab/fase2_entorno/val_entorno.m</code>: {tr('propagación, NRL, gaspl, rainpl, refracción', 'propagation, NRL, gaspl, rainpl, refraction')}</li>
            <li><code>npm test</code> {tr('en', 'in')} <code>web/</code></li>
          </ol>
        </Panel>
      </div>

      <div className="col">
        <header className="scen-head">
          <span className="scen-code">V&amp;V</span>
          <div>
            <h2>{tr('Validación frente a MATLAB', 'Validation against MATLAB')}</h2>
            <p>{tr('El motor de la web se contrasta con Phased Array System Toolbox, Radar Toolbox y los modelos ITU de MATLAB, y, donde la toolbox usa una aproximación, con un cálculo exacto independiente.', 'The web engine is checked against Phased Array System Toolbox, Radar Toolbox and the MATLAB ITU models and, where the toolbox uses an approximation, against an independent exact calculation.')}</p>
          </div>
        </header>

        <Panel title={tr('Curvas superpuestas', 'Overlaid curves')} hint={
          <span className="hint-ctl" style={{ minWidth: 300 }}>
            <select value={ov} onChange={e => setOv(e.target.value)}>
              {overlays.map(x => <option key={x.id} value={x.id}>{V(x.titulo)}</option>)}
            </select>
          </span>}>
          <LinePlot series={series} xRange={[o.x[0], o.x[o.x.length - 1]]} yRange={yr} xLabel={V(o.xLabel)} yLabel={V(o.yLabel)}
            aspect={0.42} xTicks={8} yTicks={6} xFmt={v => fmt(v, Math.abs(o.x[o.x.length - 1] - o.x[0]) < 10 ? 1 : 0)}
            yFmt={v => fmt(v, yr[1] - yr[0] < 5 ? 1 : 0)} />
        </Panel>

        <Panel title={tr('Comprobaciones', 'Checks')} hint={`${shown.length} ${tr('de', 'of')} ${checks.length}`}>
          <div className="table-wrap">
            <table className="tbl val-tbl">
              <thead><tr><th></th><th>{tr('bloque', 'block')}</th><th>{tr('caso', 'case')}</th><th>{tr('métrica', 'metric')}</th><th>error</th><th>{tr('tolerancia', 'tolerance')}</th></tr></thead>
              <tbody>
                {shown.map((c, i) => <Row key={i} c={c} />)}
              </tbody>
            </table>
          </div>
        </Panel>
      </div>

      <div className="col">
        <Panel title={tr('Hallazgos', 'Findings')}>
          <ul className="findings">
            {FINDINGS().map(f => (
              <li key={f.titulo} className={f.tipo}>
                <span className="tag-k">{f.tipo === 'bug' ? tr('error corregido', 'bug fixed') : f.tipo === 'mejora' ? tr('mejora', 'improvement') : f.tipo === 'limite' ? tr('limitación conocida', 'known limitation') : tr('diferencia de método', 'method difference')}</span>
                <b>{f.titulo}</b>
                <p>{f.texto}</p>
              </li>
            ))}
          </ul>
        </Panel>
      </div>
    </main>
  );
}

function Row({ c }: { c: Check }) {
  const st = c.info ? 'info' : passes(c) ? 'ok' : 'bad';
  const v = Math.abs(c.valor) < 1e-3 && c.valor !== 0 ? c.valor.toExponential(1) : fmt(c.valor, Math.abs(c.valor) < 1 ? 3 : 2);
  return (
    <tr className="norow" title={c.nota && V(c.nota)}>
      <td><i className={'dot-st ' + st}>{st === 'ok' ? '✓' : st === 'info' ? 'i' : '✕'}</i></td>
      <td>{V(c.grupo)}</td><td>{V(c.caso)}</td><td>{V(c.metrica)}{c.nota && <small>{V(c.nota)}</small>}</td>
      <td className={st === 'bad' ? 'bad' : ''}>{v} {c.unidad}</td><td>{fmt(c.tol, c.tol < 1 ? 3 : 1)} {c.unidad}</td>
    </tr>
  );
}
